// Validate incoming Argus payload. Branches:
//   - urls: non-empty array of https argusmedia.com URLs → continue
//   - any failure → throw with a clear message (Webhook returns 4xx)
const body = $input.first().json.body || $input.first().json;
const urls = Array.isArray(body.urls) ? body.urls : null;
if (!urls || urls.length === 0) {
  throw new Error('validation_failed: urls must be a non-empty array');
}
if (urls.length > 100) {
  throw new Error('validation_failed: urls cap is 100 per request');
}
const ARGUS_HOST = /^https:\/\/(www\.)?argusmedia\.com(\/|$)/;
const seen = new Set();
const cleaned = [];
for (const raw of urls) {
  if (typeof raw !== 'string') {
    throw new Error('validation_failed: every url must be a string');
  }
  const u = raw.trim();
  if (!u.startsWith('https://')) {
    throw new Error('validation_failed: https-only — got ' + u.slice(0, 80));
  }
  if (!ARGUS_HOST.test(u)) {
    throw new Error('validation_failed: host-not-allowed (argusmedia.com only) — got ' + u.slice(0, 80));
  }
  if (seen.has(u)) continue;
  seen.add(u);
  cleaned.push(u);
}
return [{ json: { urls: cleaned, count: cleaned.length } }];

// Shape into the /research-ingest contract. source_date deliberately
// omitted — Argus URLs come from an external scraper that doesn't carry
// per-result dates. Article-processor falls back to its own extraction.
const urls = $input.first().json.urls;
return [{
  json: {
    source_type: 'Website',
    source_name: 'Argus Media',
    source_category: 'News',
    urls: urls.map(u => ({ url: u })),
  },
}];

// Pass through content-sourcing's response + echo source_name so the
// external caller can correlate.
const upstream = $input.first().json;
return [{
  json: {
    status: upstream.status || 'queued',
    queued: upstream.queued ?? 0,
    skipped_dedup: upstream.skipped_dedup ?? 0,
    source_name: 'Argus Media',
  },
}];

// Upstream /research-ingest failed after retries. Surface upstream status
// + body so the caller can see whether it was 4xx (their fault) or 5xx.
const raw = $input.first().json;
const status = raw.statusCode || raw.status || 502;
return [{
  json: {
    status: 'error',
    upstream_status: status,
    error: typeof raw.error === 'string' ? raw.error : (raw.message || 'upstream_failed'),
    source_name: 'Argus Media',
  },
}];
